package common

import (
	"fmt"
	"math"
)

// FormatSize formats a size in bytes to human-readable string
// If apparent is true, use apparent size (bytes) otherwise disk usage (blocks)
// If si is true, use decimal SI prefixes (kB, MB, GB)
// If kib is true, always show in KiB (or kB with SI)
// If noPrefix is true, show raw bytes
func FormatSize(size int64, si bool, kib bool, noPrefix bool) string {
	if noPrefix {
		return fmt.Sprintf("%10d", size)
	}
	if kib {
		if si {
			// Show in kB
			v := float64(size) / 1000.0
			return formatFloat(v, "kB")
		}
		// Show in KiB
		v := float64(size) / 1024.0
		return formatFloat(v, "KiB")
	}
	if si {
		return formatSI(size)
	}
	return formatBinary(size)
}

func formatBinary(size int64) string {
	const (
		_          = iota
		KB float64 = 1 << (10 * iota)
		MB
		GB
		TB
		PB
		EB
	)

	v := float64(size)
	switch {
	case v < KB:
		return rightAlign(fmt.Sprintf("%d B", size), 10)
	case v < MB:
		return rightAlign(formatFloat(v/KB, "KiB"), 10)
	case v < GB:
		return rightAlign(formatFloat(v/MB, "MiB"), 10)
	case v < TB:
		return rightAlign(formatFloat(v/GB, "GiB"), 10)
	case v < PB:
		return rightAlign(formatFloat(v/TB, "TiB"), 10)
	case v < EB:
		return rightAlign(formatFloat(v/PB, "PiB"), 10)
	default:
		return rightAlign(formatFloat(v/EB, "EiB"), 10)
	}
}

func formatSI(size int64) string {
	const (
		_          = iota
		KB float64 = math.Pow(10, float64(3*iota))
		MB
		GB
		TB
		PB
		EB
	)

	v := float64(size)
	switch {
	case v < KB:
		return rightAlign(fmt.Sprintf("%d B", size), 10)
	case v < MB:
		return rightAlign(formatFloat(v/KB, "kB"), 10)
	case v < GB:
		return rightAlign(formatFloat(v/MB, "MB"), 10)
	case v < TB:
		return rightAlign(formatFloat(v/GB, "GB"), 10)
	case v < PB:
		return rightAlign(formatFloat(v/TB, "TB"), 10)
	case v < EB:
		return rightAlign(formatFloat(v/PB, "PB"), 10)
	default:
		return rightAlign(formatFloat(v/EB, "EB"), 10)
	}
}

func formatFloat(v float64, unit string) string {
	s := fmt.Sprintf("%.1f %s", v, unit)
	return s
}

func rightAlign(s string, width int) string {
	minWidth := max(width, len(s)+1)
	return fmt.Sprintf("%*s", minWidth, s)
}

func max(a, b int) int {
	if a > b {
		return a
	}
	return b
}
EOF

