package common

import (
	"io/fs"
	"os"
	"time"
)

// FileEntry represents a file or directory in the analysis
type FileEntry struct {
	Name        string
	IsDir       bool
	IsSymlink   bool
	ASize       int64  // Apparent size (bytes)
	DSize       int64  // Disk usage (bytes)
	Mtime       time.Time
	HardLink    bool
	Inode       uint64
	Device      uint64
	Flag        byte   // ' ', '@', 'H', 'e', '!', '.'
	Parent      *FileEntry
	Children    []*FileEntry
	ItemCount   int64
	ReadError   bool
	SubReadError bool
}

// GetFlag returns the flag character for display
func (f *FileEntry) GetFlag() byte {
	if f.ReadError {
		return '!'
	}
	if f.SubReadError {
		return '.'
	}
	if f.IsSymlink {
		return '@'
	}
	if f.HardLink {
		return 'H'
	}
	if f.IsDir && len(f.Children) == 0 && !f.ReadError {
		return 'e'
	}
	return ' '
}

// TotalDSize returns the total disk size (self + children)
func (f *FileEntry) TotalDSize() int64 {
	if f.IsDir {
		total := f.DSize
		for _, c := range f.Children {
			total += c.TotalDSize()
		}
		return total
	}
	return f.DSize
}

// TotalASize returns the total apparent size (self + children)
func (f *FileEntry) TotalASize() int64 {
	if f.IsDir {
		total := f.ASize
		for _, c := range f.Children {
			total += c.TotalASize()
		}
		return total
	}
	return f.ASize
}

// TotalItemCount returns the total number of items recursively
func (f *FileEntry) TotalItemCount() int64 {
	if f.IsDir {
		total := int64(1)
		for _, c := range f.Children {
			total += c.TotalItemCount()
		}
		return total
	}
	return 1
}

// LatestMtime returns the latest modification time recursively
func (f *FileEntry) LatestMtime() time.Time {
	latest := f.Mtime
	for _, c := range f.Children {
		if ct := c.LatestMtime(); ct.After(latest) {
			latest = ct
		}
	}
	return latest
}

var _ = fs.FileInfo((*FileInfoWrap)(nil))

type FileInfoWrap struct {
	info os.FileInfo
}
EOF

