cat > /workspace/analyze/scan.go << 'EOF'
package analyze

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"syscall"
	"time"

	"gdu/common"
)

// Config for scanning
type ScanConfig struct {
	IgnoreDirs        []string
	IgnoreDirPatterns []*regexp.Regexp
	IgnoreHidden      bool
	NoCross           bool
	FollowSymlinks    bool
	ShowApparent      bool
	MaxCores          int
	MaxAge            *time.Time
	MinAge            *time.Time
	Since             *time.Time
	Until             *time.Time
	IncludeTypes      map[string]bool
	ExcludeTypes      map[string]bool
}

type Scanner struct {
	config    *ScanConfig
	rootDev   uint64
	mu        sync.Mutex
	inodes    map[uint64]bool // for hard link detection
}

func NewScanner(config *ScanConfig) *Scanner {
	return &Scanner{
		config: config,
		inodes: make(map[uint64]bool),
	}
}

func (s *Scanner) ScanPath(path string) (*common.FileEntry, error) {
	info, err := os.Lstat(path)
	if err != nil {
		return nil, err
	}

	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}

	stat := info.Sys().(*syscall.Stat_t)
	s.rootDev = stat.Dev

	entry := &common.FileEntry{
		Name:  abs,
		IsDir: info.IsDir(),
		Mtime: info.ModTime(),
	}

	if info.IsDir() {
		entry.DSize = 4096
		entry.ASize = int64(info.Size())
		s.scanDir(entry, abs)
	} else {
		entry.DSize = int64(stat.Blocks) * 512
		entry.ASize = info.Size()
	}

	return entry, nil
}

func (s *Scanner) shouldIgnore(path string) bool {
	for _, dir := range s.config.IgnoreDirs {
		if dir == path {
			return true
		}
		if filepath.IsAbs(dir) && dir == path {
			return true
		}
	}

	for _, pat := range s.config.IgnoreDirPatterns {
		if pat.MatchString(path) {
			return true
		}
	}

	return false
}

func (s *Scanner) scanDir(dirEntry *common.FileEntry, dirPath string) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		dirEntry.ReadError = true
		return
	}

	for _, de := range entries {
		name := de.Name()
		fullPath := filepath.Join(dirPath, name)

		// Check if should ignore
		if s.shouldIgnore(fullPath) {
			continue
		}

		// Check hidden
		if s.config.IgnoreHidden && strings.HasPrefix(name, ".") && de.IsDir() {
			continue
		}

		info, err := os.Lstat(fullPath)
		if err != nil {
			continue
		}

		stat := info.Sys().(*syscall.Stat_t)

		// No cross device
		if s.config.NoCross && stat.Dev != s.rootDev {
			continue
		}

		entry := &common.FileEntry{
			Name:   name,
			Parent: dirEntry,
			Mtime:  info.ModTime(),
		}

		if info.Mode()&os.ModeSymlink != 0 {
			// Symlink
			entry.IsSymlink = true
			if s.config.FollowSymlinks {
				// Follow symlink for files
				realInfo, err := os.Stat(fullPath)
				if err == nil && !realInfo.IsDir() {
					realStat := realInfo.Sys().(*syscall.Stat_t)
					entry.DSize = int64(realStat.Blocks) * 512
					entry.ASize = realInfo.Size()
					entry.IsSymlink = false
				} else {
					entry.ASize = info.Size()
					entry.DSize = 0
					entry.IsSymlink = true
				}
			} else {
				entry.ASize = info.Size()
				entry.DSize = 0
			}
		} else if info.IsDir() {
			entry.IsDir = true
			entry.DSize = 4096
			entry.ASize = int64(info.Size())

			// Check type filter for directories
			if len(s.config.IncludeTypes) > 0 {
				// Include only matching types - for dirs, scan and include if non-empty match
			}

			if !s.shouldIgnore(fullPath) {
				s.scanDir(entry, fullPath)
			}
		} else {
			// Regular file
