package common

import (
	"fmt"
)

// FormatSize formats a size in bytes for regular (per-file) mode
// Returns a string right-aligned to at least 10 chars (with at least 1 leading space)
func FormatSize(size int64, si bool, kib bool, noPrefix bool) string {
	if noPrefix {
		s := fmt.Sprintf("%d", size)
		w := 10
		if len(s)+1 > w {
			w = len(s) + 1
		}
		return fmt.Sprintf("%*s", w, s)
	}
	if kib {
		if si {
			v := float64(size) / 1000.0
			s := fmt.Sprintf("%.1f kB", v)
			return rightAlignMin10(s)
		}
		v := float64(size) / 1024.0
		s := fmt.Sprintf("%.1f KiB", v)
		return rightAlignMin10(s)
	}
	if si {
		return formatSIMin10(size)
	}
	return formatBinaryMin10(size)
}

// FormatSizeSummarize formats a size for summarize/depth/top modes
// Returns a string right-aligned to at least 9 chars (NO required leading space)
func FormatSizeSummarize(size int64, si bool, kib bool, noPrefix bool) string {
	if noPrefix {
		s := fmt.Sprintf("%d", size)
		w := 9
		if len(s) > w {
			w = len(s)
		}
		return fmt.Sprintf("%*s", w, s)
	}
	if kib {
		if si {
			v := float64(size) / 1000.0
			s := fmt.Sprintf("%.1f kB", v)
			return rightAlignMin9(s)
		}
		v := float64(size) / 1024.0
		s := fmt.Sprintf("%.1f KiB", v)
		return rightAlignMin9(s)
	}
	if si {
		return formatSIMin9(size)
	}
	return formatBinaryMin9(size)
}

func rightAlignMin10(s string) string {
	w := 10
	if len(s)+1 > w {
		w = len(s) + 1
	}
	return fmt.Sprintf("%*s", w, s)
}

func rightAlignMin9(s string) string {
	w := 9
	if len(s) > w {
		w = len(s)
	}
	return fmt.Sprintf("%*s", w, s)
}

const (
	KiB int64 = 1024
	MiB       = KiB * 1024
	GiB       = MiB * 1024
	TiB       = GiB * 1024
	PiB       = TiB * 1024
	EiB       = PiB * 1024
)

const (
	KB float64 = 1e3
	MB         = 1e6
	GB         = 1e9
	TB         = 1e12
	PB         = 1e15
	EB         = 1e18
)

func sizeStringBinary(size int64) string {
	v := float64(size)
	switch {
	case size < KiB:
		return fmt.Sprintf("%d B", size)
	case size < MiB:
		return fmt.Sprintf("%.1f KiB", v/float64(KiB))
	case size < GiB:
		return fmt.Sprintf("%.1f MiB", v/float64(MiB))
	case size < TiB:
		return fmt.Sprintf("%.1f GiB", v/float64(GiB))
	case size < PiB:
		return fmt.Sprintf("%.1f TiB", v/float64(TiB))
	case size < EiB:
		return fmt.Sprintf("%.1f PiB", v/float64(PiB))
	default:
		return fmt.Sprintf("%.1f EiB", v/float64(EiB))
	}
}

func sizeStringSI(size int64) string {
	v := float64(size)
	switch {
