	case v < PB:
		return fmt.Sprintf("%.1f TB", v/TB)
	case v < EB:
		return fmt.Sprintf("%.1f PB", v/PB)
	default:
		return fmt.Sprintf("%.1f EB", v/EB)
	}
}

func formatBinaryMin10(size int64) string {
	return rightAlignMin10(sizeStringBinary(size))
}

func formatBinaryMin9(size int64) string {
	return rightAlignMin9(sizeStringBinary(size))
}

func formatSIMin10(size int64) string {
	return rightAlignMin10(sizeStringSI(size))
}

func formatSIMin9(size int64) string {
	return rightAlignMin9(sizeStringSI(size))
}
EOF

