			entry.IsSymlink = true
			entry.NotrReg = true
			if s.config.FollowSymlinks {
				realInfo, ferr := os.Stat(fullPath)
				if ferr == nil && !realInfo.IsDir() {
					realStat := realInfo.Sys().(*syscall.Stat_t)
					entry.DSize = int64(realStat.Blocks) * 512
					entry.ASize = realInfo.Size()
					entry.IsSymlink = false
					entry.NotrReg = false
				}
			}
		} else if isDir {
			entry.IsDir = true
			entry.DSize = 4096

			if !s.shouldIgnorePath(fullPath) {
				s.scanDir(entry, fullPath)
			}
		} else {
			// Regular file (or special file)
			isReg := info.Mode().IsRegular()
			if !isReg {
				entry.NotrReg = true
			}

			entry.DSize = int64(stat.Blocks) * 512
			entry.ASize = info.Size()
			entry.Inode = stat.Ino
			entry.Device = stat.Dev

			// Check for hard links
			if isReg && stat.Nlink > 1 {
				s.mu.Lock()
				key := stat.Ino + stat.Dev*1000000007
				if s.inodes[key] {
					entry.HardLink = true
				} else {
					s.inodes[key] = true
				}
				s.mu.Unlock()
			}

			// Type filtering (only for regular files)
			if isReg {
				ext := strings.TrimPrefix(filepath.Ext(name), ".")
				if len(s.config.IncludeTypes) > 0 {
					if !s.config.IncludeTypes[ext] {
						continue
					}
				}
				if len(s.config.ExcludeTypes) > 0 {
					if s.config.ExcludeTypes[ext] {
						continue
					}
				}
			}

			// Age/time filtering
			mtime := info.ModTime()
			if s.config.MaxAge != nil && mtime.Before(*s.config.MaxAge) {
				continue
			}
			if s.config.MinAge != nil && mtime.After(*s.config.MinAge) {
				continue
			}
			if s.config.Since != nil {
				// Since: include files with mtime >= WHEN
				if mtime.Before(*s.config.Since) {
					continue
				}
			}
			if s.config.Until != nil {
				// Until: include files with mtime <= WHEN
				if mtime.After(*s.config.Until) {
					continue
				}
			}
		}

		dirEntry.Children = append(dirEntry.Children, entry)
	}
}
