	Ino    uint64 `json:"ino,omitempty"`
	HlnkC  bool   `json:"hlnkc,omitempty"`
	Notreg bool   `json:"notreg,omitempty"`
}

// ExportJSON exports the file tree to a JSON file
func ExportJSON(root *common.FileEntry, path string, version string) error {
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("creating output file: %w", err)
	}
	defer f.Close()

	header := jsonHeader{
		Progname:  "gdu",
		Progver:   version,
		Timestamp: time.Now().Unix(),
	}

	// Write the outer array start
	fmt.Fprintf(f, "[1,2,")

	// Write header
	hBytes, _ := json.Marshal(header)
	f.Write(hBytes)
	fmt.Fprintf(f, ",\n")

	// Write the tree
	writeJSONEntry(f, root, true)
	fmt.Fprintf(f, "]\n")

	return nil
}

func writeJSONEntry(w io.Writer, entry *common.FileEntry, isRoot bool) {
	if entry.IsDir {
		// Start array for dir
		if isRoot {
			fmt.Fprintf(w, "[")
		}
		// Write dir header
		dirData := map[string]interface{}{
			"name":  entry.Name,
			"mtime": entry.Mtime.Unix(),
		}
		hBytes, _ := json.Marshal(dirData)
		w.Write(hBytes)

		for _, child := range entry.Children {
			fmt.Fprintf(w, ",\n")
			writeJSONEntry(w, child, false)
		}

		if isRoot {
			fmt.Fprintf(w, "]")
		}
	} else {
		// File entry
		fData := jsonFile{
			Name:  entry.Name,
			Mtime: entry.Mtime.Unix(),
		}
		if entry.ASize > 0 {
			fData.ASize = entry.ASize
		}
		if entry.DSize > 0 {
			fData.DSize = entry.DSize
		}
		if entry.Inode > 0 {
			fData.Ino = entry.Inode
			fData.HlnkC = true
		}
		if entry.IsSymlink || entry.NotrReg {
			fData.Notreg = true
		}
		bytes, _ := json.Marshal(fData)
		w.Write(bytes)
	}
}

// Actually the JSON export needs to handle dirs as nested arrays differently
// Let me rewrite this...

func writeJSONDir(w io.Writer, entry *common.FileEntry) {
	fmt.Fprintf(w, "[")
	// First element: dir header
	dirData := map[string]interface{}{
		"name":  entry.Name,
		"mtime": entry.Mtime.Unix(),
	}
	hBytes, _ := json.Marshal(dirData)
	w.Write(hBytes)

	for _, child := range entry.Children {
		fmt.Fprintf(w, ",\n")
		if child.IsDir {
			writeJSONDir(w, child)
		} else {
			writeJSONFile(w, child)
		}
	}
	fmt.Fprintf(w, "]")
}

func writeJSONFile(w io.Writer, entry *common.FileEntry) {
	fData := jsonFile{
		Name:  entry.Name,
		Mtime: entry.Mtime.Unix(),
	}
	if entry.ASize > 0 {
		fData.ASize = entry.ASize
	}
	if entry.DSize > 0 {
		fData.DSize = entry.DSize
	}
	if entry.HardLink && entry.Inode > 0 {
		fData.Ino = entry.Inode
		fData.HlnkC = true
	}
	if entry.IsSymlink || entry.NotrReg {
		fData.Notreg = true
	}
	bytes, _ := json.Marshal(fData)
	w.Write(bytes)
}

// ExportJSONV2 is the actual export function
func ExportJSONV2(root *common.FileEntry, path string, version string) error {
	f, err := os.Create(path)
	if err != nil {
		return fmt.Errorf("creating output file: %w", err)
	}
	defer f.Close()

	header := jsonHeader{
		Progname:  "gdu",
		Progver:   version,
		Timestamp: time.Now().Unix(),
	}

	fmt.Fprintf(f, "[1,2,")
	hBytes, _ := json.Marshal(header)
	f.Write(hBytes)
	fmt.Fprintf(f, ",\n")
	writeJSONDir(f, root)
	fmt.Fprintf(f, "]\n")

	return nil
}

// ImportJSON reads a JSON file and builds a file entry tree
func ImportJSON(path string) (*common.FileEntry, error) {
	f, err := os.Open(path)
	if err != nil {
		return nil, fmt.Errorf("opening input file: %w", err)
	}
	defer f.Close()

	data, err := io.ReadAll(f)
	if err != nil {
		return nil, fmt.Errorf("reading input file: %w", err)
	}

	// Parse the raw JSON structure
	var raw []interface{}
	if err := json.Unmarshal(data, &raw); err != nil {
		return nil, fmt.Errorf("parsing JSON: %w", err)
	}

	// raw[0] = 1 (version marker)
	// raw[1] = 2 (sub-version)
	// raw[2] = header object
	// raw[3] = dir tree

	if len(raw) < 4 {
		return nil, fmt.Errorf("invalid JSON format")
	}

	// Parse the tree (raw[3])
	tree, ok := raw[3].([]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid tree format")
	}

	root := parseJSONDir(tree)
	return root, nil
}

func parseJSONDir(arr []interface{}) *common.FileEntry {
	if len(arr) == 0 {
		return nil
	}

	// First element is dir header
	headerMap, ok := arr[0].(map[string]interface{})
	if !ok {
		return nil
	}

	dir := &common.FileEntry{
		IsDir: true,
		DSize: 4096,
	}

	if name, ok := headerMap["name"].(string); ok {
		dir.Name = name
	}
	if mtime, ok := headerMap["mtime"].(float64); ok {
		dir.Mtime = time.Unix(int64(mtime), 0)
	}
	if asize, ok := headerMap["asize"].(float64); ok {
		dir.ASize = int64(asize)
	}

	// Process children (arr[1:])
	for _, item := range arr[1:] {
		switch v := item.(type) {
		case []interface{}:
			// Subdirectory
			subdir := parseJSONDir(v)
			if subdir != nil {
				subdir.Parent = dir
				dir.Children = append(dir.Children, subdir)
			}
		case map[string]interface{}:
			// File
			child := parseJSONFile(v)
			if child != nil {
				child.Parent = dir
				dir.Children = append(dir.Children, child)
			}
		}
	}

	return dir
}

func parseJSONFile(m map[string]interface{}) *common.FileEntry {
	entry := &common.FileEntry{}

	if name, ok := m["name"].(string); ok {
		entry.Name = name
	}
	if asize, ok := m["asize"].(float64); ok {
		entry.ASize = int64(asize)
	}
	if dsize, ok := m["dsize"].(float64); ok {
		entry.DSize = int64(dsize)
	}
	if mtime, ok := m["mtime"].(float64); ok {
		entry.Mtime = time.Unix(int64(mtime), 0)
	}
	if ino, ok := m["ino"].(float64); ok {
		entry.Inode = uint64(ino)
	}
	if hlnk, ok := m["hlnkc"].(bool); ok && hlnk {
		entry.HardLink = true
	}
	if notreg, ok := m["notreg"].(bool); ok && notreg {
		entry.IsSymlink = true
		entry.NotrReg = true
	}

	return entry
}
