package output

import (
	"fmt"
	"io"
	"os"
	"sort"
	"strings"

	"gdu/common"
)

// PrintConfig holds configuration for printing
type PrintConfig struct {
	ShowApparent bool
	SI           bool
	KiB          bool
	NoPrefix     bool
	ReverseSort  bool
	Top          int
	Depth        int
	Summarize    bool
}

// formatSize formats a size based on the config
func formatSize(size int64, cfg *PrintConfig) string {
	return common.FormatSize(size, cfg.SI, cfg.KiB, cfg.NoPrefix)
}

func formatSizeSummarize(size int64, cfg *PrintConfig) string {
	return common.FormatSizeSummarize(size, cfg.SI, cfg.KiB, cfg.NoPrefix)
}

// getDisplaySize returns the size to display for an entry
func getDisplaySize(entry *common.FileEntry, cfg *PrintConfig) int64 {
	if cfg.ShowApparent {
		return entry.TotalASize()
	}
	return entry.TotalDSize()
}

// PrintResults prints the analysis results to stdout
func PrintResults(root *common.FileEntry, cfg *PrintConfig) {
	w := os.Stdout

	if cfg.Summarize {
		printSummarize(w, root, cfg)
		return
	}

	if cfg.Top > 0 {
		printTop(w, root, cfg)
		return
	}

	if cfg.Depth > 0 {
		printDepth(w, root, cfg, 1)
		return
	}

	// Default: show direct children sorted by size
	printChildren(w, root, cfg)
}

func printSummarize(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	size := getDisplaySize(root, cfg)
	sizeStr := formatSizeSummarize(size, cfg)
	// Get the last component of the path as name
	name := root.Name
	parts := strings.Split(strings.TrimSuffix(name, "/"), "/")
	basename := parts[len(parts)-1]
	fmt.Fprintf(w, "%s %s\n", sizeStr, basename)
}

func printDepth(w io.Writer, entry *common.FileEntry, cfg *PrintConfig, currentDepth int) {
	size := getDisplaySize(entry, cfg)
	sizeStr := formatSizeSummarize(size, cfg)
	fmt.Fprintf(w, "%s %s\n", sizeStr, entry.Name)

	if currentDepth >= cfg.Depth {
		return
	}

	// Sort children
	children := make([]*common.FileEntry, len(entry.Children))
	copy(children, entry.Children)
	sortBySize(children, cfg)

	for _, child := range children {
		if child.IsDir {
			printDepth(w, child, cfg, currentDepth+1)
		} else {
			size := getDisplaySize(child, cfg)
			sizeStr := formatSizeSummarize(size, cfg)
			fmt.Fprintf(w, "%s %s\n", sizeStr, child.Name)
		}
	}
}

func printTop(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	// Collect all files recursively
	var files []*common.FileEntry
	collectFiles(root, &files)

	// Sort by apparent size descending
	sort.SliceStable(files, func(i, j int) bool {
		return files[i].TotalASize() > files[j].TotalASize()
	})

	// Print top N
	count := cfg.Top
	if count > len(files) {
		count = len(files)
	}

	for i := 0; i < count; i++ {
		f := files[i]
		size := getDisplaySize(f, cfg)
		sizeStr := formatSizeSummarize(size, cfg)
		fmt.Fprintf(w, "%s %s\n", sizeStr, f.Name)
	}
}

func collectFiles(entry *common.FileEntry, files *[]*common.FileEntry) {
	if entry.IsDir {
		for _, child := range entry.Children {
			collectFiles(child, files)
		}
	} else {
		*files = append(*files, entry)
	}
}

func printChildren(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	children := make([]*common.FileEntry, len(root.Children))
	copy(children, root.Children)
	sortBySize(children, cfg)

	for _, child := range children {
		size := getDisplaySize(child, cfg)
		sizeStr := formatSize(size, cfg)
		flag := child.GetFlag()
		name := child.GetDisplayName()
		fmt.Fprintf(w, "%c%s %s\n", flag, sizeStr, name)
	}
}

func sortBySize(entries []*common.FileEntry, cfg *PrintConfig) {
	sort.SliceStable(entries, func(i, j int) bool {
		si := getDisplaySize(entries[i], cfg)
		sj := getDisplaySize(entries[j], cfg)
		if cfg.ReverseSort {
			return si < sj
		}
		return si > sj
	})
}
EOF

