	if entry.IsDir {
		for _, child := range entry.Children {
			collectFiles(child, files)
		}
	} else {
		*files = append(*files, entry)
	}
}

func printChildren(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	children := make([]*common.FileEntry, len(root.Children))
	copy(children, root.Children)
	sortBySize(children, cfg)

	for _, child := range children {
		size := getDisplaySize(child, cfg)
		sizeStr := formatSize(size, cfg)
		flag := child.GetFlag()
		name := child.GetDisplayName()
		fmt.Fprintf(w, "%c%s %s\n", flag, sizeStr, name)
	}
}

func sortBySize(entries []*common.FileEntry, cfg *PrintConfig) {
	sort.SliceStable(entries, func(i, j int) bool {
		si := getDisplaySize(entries[i], cfg)
		sj := getDisplaySize(entries[j], cfg)
		if cfg.ReverseSort {
			return si < sj
		}
		return si > sj
	})
}
