package tui

import (
	"fmt"
	"math"
	"os"
	"os/exec"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"time"
	"unicode/utf8"
	"unsafe"

	"gdu/analyze"
	"gdu/common"
)

// TUIConfig holds configuration for the TUI
type TUIConfig struct {
	ShowApparent    bool
	ShowRelativeSize bool
	ShowItemCount   bool
	ShowMtime       bool
	NoColor         bool
	NoUnicode       bool
	Mouse           bool
	NoDelete        bool
	NoSpawnShell    bool
	ScanConfig      *analyze.ScanConfig
	Version         string
	BuildTime       string
	BuildUser       string
}

// TUI is the terminal user interface
type TUI struct {
	cfg          *TUIConfig
	root         *common.FileEntry
	currentDir   *common.FileEntry
	cursor       int
	offset       int // scroll offset
	width        int
	height       int
	sortBy       string // "size", "name", "itemCount", "mtime"
	sortOrder    string // "asc", "desc"
	showApparent bool
	showRelative bool
	filterText   string
	filterDirs   bool
	filterNegate bool
	markedItems  map[*common.FileEntry]bool
	showInfo     bool
	showFilter   bool
	showHelp     bool
	showDevInfo  bool
	message      string
	messageTime  time.Time
}

// Block element characters for size bar
var blockChars = []rune{' ', '▏', '▎', '▍', '▌', '▋', '▊', '▉', '█'}
var blockCharsASCII = []string{" ", "#"}

// ANSI color codes
const (
	colorReset     = "\033[0m"
	colorBold      = "\033[1m"
	// Header/footer: black on blue (#2479D0 → use [44m blue or [46m cyan)
	colorHeader    = "\033[30;46m" // black on cyan
	colorSelected  = "\033[1;37;42m" // bold white on green
	// Numbers: bold dark yellow/orange approximation
	colorNumber    = "\033[1;33m" // bold yellow (closest to #e67100)
	colorDir       = "\033[36m"   // cyan (closest to #3498db)
	colorSymlink   = "\033[36m"   // cyan
	colorHardLink  = "\033[33m"   // yellow
)

// New creates a new TUI instance
func New(cfg *TUIConfig) *TUI {
	t := &TUI{
		cfg:          cfg,
		sortBy:       "size",
		sortOrder:    "desc",
		showApparent: cfg.ShowApparent,
		showRelative: cfg.ShowRelativeSize,
		markedItems:  make(map[*common.FileEntry]bool),
	}
	return t
}

// Run starts the TUI
func (t *TUI) Run(path string) error {
	// Set raw terminal mode
	oldState, err := makeRaw(os.Stdin.Fd())
	if err != nil {
		return err
	}
	defer restore(os.Stdin.Fd(), oldState)

	// Get terminal size
	t.width, t.height = getTermSize()

	// Hide cursor
	fmt.Print("\033[?25l")
	// Clear screen
	fmt.Print("\033[2J\033[H")
	defer func() {
		fmt.Print("\033[?25h") // show cursor
		fmt.Print("\033[2J\033[H") // clear screen
	}()

	// Scan the path
	scanner := analyze.NewScanner(t.cfg.ScanConfig)

	showProgress := true
	if showProgress {
		t.drawProgress("Scanning...")
	}

	root, err := scanner.ScanPath(path)
	if err != nil {
		return err
	}

	t.root = root
	if root.IsDir {
		t.currentDir = root
	} else {
		// If scanning a file, create a virtual parent dir
		parent := &common.FileEntry{
			Name:     filepath.Dir(root.Name),
			IsDir:    true,
			DSize:    4096,
			Children: []*common.FileEntry{root},
		}
		root.Parent = parent
		t.currentDir = parent
	}

	// Main event loop
	t.render()

	buf := make([]byte, 16)
	for {
		n, err := os.Stdin.Read(buf)
		if err != nil {
			break
		}
		if n == 0 {
			continue
		}

		key := buf[:n]
		if t.handleKey(key) {
			break
		}

		// Re-render
		t.width, t.height = getTermSize()
		t.render()
	}

	return nil
}

func (t *TUI) drawProgress(msg string) {
	fmt.Printf("\033[2J\033[H%s\n", msg)
}

func (t *TUI) currentItems() []*common.FileEntry {
	items := make([]*common.FileEntry, len(t.currentDir.Children))
	copy(items, t.currentDir.Children)
	t.sortItems(items)
	return items
}

func (t *TUI) sortItems(items []*common.FileEntry) {
	sort.SliceStable(items, func(i, j int) bool {
		a, b := items[i], items[j]
		var less bool
		switch t.sortBy {
		case "name":
			less = a.Name < b.Name
		case "itemCount":
			less = a.TotalItemCount() < b.TotalItemCount()
		case "mtime":
			less = a.LatestMtime().Before(b.LatestMtime())
		default: // "size"
			var sa, sb int64
			if t.showApparent {
				sa = a.TotalASize()
				sb = b.TotalASize()
			} else {
				sa = a.TotalDSize()
				sb = b.TotalDSize()
			}
			less = sa < sb
		}
		if t.sortOrder == "desc" {
			return !less
		}
		return less
	})
}

func (t *TUI) getItemSize(entry *common.FileEntry) int64 {
	if t.showApparent {
		return entry.TotalASize()
	}
	return entry.TotalDSize()
}

func (t *TUI) getDirTotalSize() int64 {
	// Total = sum of all non-hardlink children
	var total int64
	for _, child := range t.currentDir.Children {
		if !child.HardLink {
			total += t.getItemSize(child)
		}
	}
	return total
}

func (t *TUI) render() {
	// Clear screen
	fmt.Print("\033[2J\033[H")

	items := t.currentItems()

	// Ensure cursor is in bounds
	totalItems := len(items)
	hasParent := t.currentDir.Parent != nil
	totalRows := totalItems
	if hasParent {
		totalRows++ // for ".." entry
	}

	if t.cursor >= totalRows {
		t.cursor = totalRows - 1
	}
	if t.cursor < 0 {
		t.cursor = 0
	}

	// Visible area
	listHeight := t.height - 3 // header (1) + dir-title (1) + footer (1)
	if listHeight < 1 {
		listHeight = 1
	}

	// Scroll to keep cursor visible
	if t.cursor < t.offset {
		t.offset = t.cursor
	}
	if t.cursor >= t.offset+listHeight {
		t.offset = t.cursor - listHeight + 1
	}

	// Draw header
	t.drawHeader()

	// Draw current dir title
	t.drawDirTitle()

	// Draw items
	for row := 0; row < listHeight; row++ {
		itemIdx := t.offset + row
		isSelected := (itemIdx == t.cursor)

		if hasParent {
			if itemIdx == 0 {
				t.drawParentEntry(isSelected)
				continue
			}
			itemIdx-- // adjust for parent entry
		}

		if itemIdx < 0 || itemIdx >= len(items) {
			fmt.Println()
			continue
		}

		t.drawItem(items[itemIdx], isSelected)
	}

	// Draw footer
	t.drawFooter()

	// Draw overlay if needed
	if t.showHelp {
		t.drawHelp()
	} else if t.showInfo {
		selected := t.getSelectedItem()
		if selected != nil {
			t.drawItemInfo(selected)
		}
	}
}

func (t *TUI) drawHeader() {
	title := " gdu ~ Use arrow keys to navigate, press ? for help"
	if t.cfg.NoColor {
		fmt.Printf("%-*s\n", t.width-1, title)
	} else {
		fmt.Printf("%s%-*s%s\n", colorHeader, t.width-1, title, colorReset)
	}
}

func (t *TUI) drawDirTitle() {
	title := fmt.Sprintf(" --- %s ---", t.currentDir.Name)
	if t.cfg.NoColor {
		fmt.Printf("%s\n", colorBold+title+colorReset)
	} else {
		fmt.Printf("%s%s%s\n", colorBold, title, colorReset)
	}
}

func (t *TUI) drawParentEntry(isSelected bool) {
	// ".." entry
	line := fmt.Sprintf("%25s/..", "")
	if isSelected {
		if t.cfg.NoColor {
			fmt.Printf("%-*s\n", t.width-1, line)
		} else {
			fmt.Printf("%s%-*s%s\n", colorSelected, t.width-1, line, colorReset)
		}
	} else {
		fmt.Println(line)
	}
}

func (t *TUI) drawItem(entry *common.FileEntry, isSelected bool) {
	size := t.getItemSize(entry)
	sizeStr := formatSize(size, false, false, false)
	flag := entry.GetFlag()
	name := entry.GetDisplayName()

	// Size bar
	total := t.getDirTotalSize()
	barStr := t.buildBar(size, total)

	var line string
	if t.cfg.NoColor {
		line = fmt.Sprintf("%c%s %s%s", flag, sizeStr, barStr, name)
		if isSelected {
			fmt.Printf("%-*s\n", t.width-1, line)
		} else {
			fmt.Println(line)
		}
	} else {
		if isSelected {
			// Selected row: bold white on green background
			line = fmt.Sprintf("%c%s %s%s", flag, sizeStr, barStr, name)
			fmt.Printf("%s%-*s%s\n", colorSelected, t.width-1, line, colorReset)
		} else {
			// Normal row with colors
			numStr := colorNumber + sizeStr + colorReset
			var nameStr string
			if entry.IsDir {
				nameStr = colorDir + name + colorReset
			} else if entry.IsSymlink {
				nameStr = colorSymlink + name + colorReset
			} else if entry.HardLink {
				nameStr = colorHardLink + name + colorReset
			} else {
				nameStr = name
			}
			fmt.Printf("%c%s %s%s\n", flag, numStr, barStr, nameStr)
		}
	}
}

func (t *TUI) buildBar(size, total int64) string {
	barWidth := 10
	var sb strings.Builder

	if total <= 0 || size <= 0 {
		if t.cfg.NoUnicode {
			sb.WriteString(strings.Repeat(" ", barWidth))
			sb.WriteRune('|')
		} else {
			sb.WriteString(strings.Repeat(" ", barWidth))
			sb.WriteRune('▏')
		}
		return sb.String()
	}

	ratio := float64(size) / float64(total)
	filled := ratio * float64(barWidth)
	fullCells := int(filled)
	if fullCells > barWidth {
		fullCells = barWidth
	}
	rem := filled - float64(fullCells)

	if t.cfg.NoUnicode {
		// ASCII bar: use '#' for full, space for empty
		for i := 0; i < fullCells; i++ {
			sb.WriteByte('#')
		}
		partialASCII := int(rem * 2) // 0 or 1
		if partialASCII > 0 && fullCells < barWidth {
			sb.WriteByte('#')
			fullCells++
		}
		for i := fullCells; i < barWidth; i++ {
			sb.WriteByte(' ')
		}
		sb.WriteByte('|')
	} else {
		// Unicode block chars
		for i := 0; i < fullCells; i++ {
			sb.WriteRune('█')
		}
		partialIdx := int(rem * float64(len(blockChars)-1))
		if partialIdx > 0 && fullCells < barWidth {
			sb.WriteRune(blockChars[partialIdx])
			fullCells++
		}
		for i := fullCells; i < barWidth; i++ {
			sb.WriteByte(' ')
		}
		sb.WriteRune('▏')
	}

	return sb.String()
}

func (t *TUI) drawFooter() {
	// Calculate totals
	var totalDisk, totalApparent, itemCount int64
	for _, child := range t.currentDir.Children {
		totalDisk += child.TotalDSize()
		totalApparent += child.TotalASize()
		itemCount += child.TotalItemCount()
	}
	totalDisk += t.currentDir.DSize
	totalApparent += t.currentDir.ASize

	diskStr := formatSize(totalDisk, false, false, false)
	appStr := formatSize(totalApparent, false, false, false)

	sortDesc := t.sortBy
	if t.sortOrder == "desc" {
		sortDesc += " desc"
	} else {
		sortDesc += " asc"
	}

	footer := fmt.Sprintf(" Total disk usage: %s Apparent size: %s Items: %d Sorting by: %s",
		strings.TrimSpace(diskStr), strings.TrimSpace(appStr), itemCount, sortDesc)

	if t.cfg.NoColor {
		fmt.Printf("%-*s", t.width-1, footer)
	} else {
		fmt.Printf("%s%-*s%s", colorHeader, t.width-1, footer, colorReset)
	}
}

func (t *TUI) getSelectedItem() *common.FileEntry {
	items := t.currentItems()
	hasParent := t.currentDir.Parent != nil

	idx := t.cursor
	if hasParent {
		if idx == 0 {
			return nil // parent entry selected
		}
		idx--
	}

	if idx >= 0 && idx < len(items) {
		return items[idx]
	}
	return nil
}

func (t *TUI) handleKey(key []byte) bool {
	s := string(key)

	if t.showHelp {
		// Any key closes help
		t.showHelp = false
		return false
	}

	if t.showInfo {
		t.showInfo = false
		return false
	}

	switch {
	case s == "q" || s == "Q" || s == "\x03": // q, Q, Ctrl+C
		if s == "Q" {
			// Print current directory path
			fmt.Printf("\n%s\n", t.currentDir.Name)
		}
		return true

	case s == "?" : // help
		t.showHelp = true

	case s == "\033[A" || s == "k": // up
		if t.cursor > 0 {
			t.cursor--
		}

	case s == "\033[B" || s == "j": // down
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		if t.cursor < maxCursor {
			t.cursor++
		}

	case s == "\033[C" || s == "\r" || s == "l" || s == "\n": // right/enter
		t.enterSelected()

	case s == "\033[D" || s == "h": // left
		t.goToParent()

	case s == "g" || s == "\033[1~" || s == "\033[H": // home/g - go to top
		t.cursor = 0

	case s == "G" || s == "\033[4~" || s == "\033[F": // end/G - go to bottom
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		t.cursor = maxCursor

	case s == "\033[5~": // PgUp
		t.cursor -= t.height - 3
		if t.cursor < 0 {
			t.cursor = 0
		}

	case s == "\033[6~": // PgDn
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		t.cursor += t.height - 3
		if t.cursor > maxCursor {
			t.cursor = maxCursor
		}

	case s == "n": // sort by name
		if t.sortBy == "name" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "name"
			t.sortOrder = "asc"
		}

	case s == "s": // sort by size
		if t.sortBy == "size" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "size"
			t.sortOrder = "desc"
		}

	case s == "c": // sort by item count
		if t.sortBy == "itemCount" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "itemCount"
			t.sortOrder = "desc"
		}

	case s == "m": // sort by mtime (or toggle mtime display in interactive? no, here it's sort)
		if t.sortBy == "mtime" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "mtime"
			t.sortOrder = "desc"
		}

	case s == "a": // toggle apparent size
		t.showApparent = !t.showApparent

	case s == "B": // toggle relative size
		t.showRelative = !t.showRelative

	case s == "r": // rescan
		t.rescan()

	case s == "i": // show info
		t.showInfo = !t.showInfo

	case s == "d": // delete
		if !t.cfg.NoDelete {
			t.deleteSelected()
		}

	case s == " ": // mark/unmark
		item := t.getSelectedItem()
		if item != nil {
			if t.markedItems[item] {
				delete(t.markedItems, item)
			} else {
				t.markedItems[item] = true
			}
		}

	case s == "u": // unmark all
		t.markedItems = make(map[*common.FileEntry]bool)

	case s == "b": // spawn shell
		if !t.cfg.NoSpawnShell {
			t.spawnShell()
		}

	case s == "v": // view file content
		item := t.getSelectedItem()
		if item != nil && !item.IsDir {
			t.viewFile(item)
		}
	}

	return false
}

func (t *TUI) enterSelected() {
	items := t.currentItems()
	hasParent := t.currentDir.Parent != nil

	idx := t.cursor
	if hasParent {
		if idx == 0 {
			t.goToParent()
			return
		}
		idx--
	}

	if idx >= 0 && idx < len(items) {
		item := items[idx]
		if item.IsDir {
			t.currentDir = item
			t.cursor = 0
			t.offset = 0
		}
	}
}

func (t *TUI) goToParent() {
	if t.currentDir.Parent != nil {
		parent := t.currentDir.Parent
		// Find the current dir in parent's children to set cursor
		t.currentDir = parent
		t.cursor = 0
		t.offset = 0
	}
}

func (t *TUI) rescan() {
	scanner := analyze.NewScanner(t.cfg.ScanConfig)

	path := t.currentDir.Name
	entry, err := scanner.ScanPath(path)
	if err != nil {
		return
	}

	// Update current dir
	if t.currentDir == t.root {
		t.root = entry
		t.currentDir = entry
	} else {
		t.currentDir.Children = entry.Children
	}
	t.cursor = 0
	t.offset = 0
}

func (t *TUI) deleteSelected() {
	item := t.getSelectedItem()
	if item == nil {
		return
	}

	// Confirm dialog would be nice but let's skip for now
	path := item.Name
	if item.IsDir {
		os.RemoveAll(path)
	} else {
		os.Remove(path)
	}

	// Remove from parent's children
	parent := t.currentDir
	for i, c := range parent.Children {
		if c == item {
			parent.Children = append(parent.Children[:i], parent.Children[i+1:]...)
			break
		}
	}

	if t.cursor >= len(parent.Children) {
		t.cursor = len(parent.Children) - 1
	}
	if t.cursor < 0 {
		t.cursor = 0
	}
}

func (t *TUI) spawnShell() {
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	// Restore terminal
	restore(os.Stdin.Fd(), nil)
	fmt.Print("\033[?25h")
	fmt.Print("\033[2J\033[H")

	cmd := exec.Command(shell)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Dir = t.currentDir.Name
	cmd.Run()

	// Re-enter raw mode (done by caller)
}

func (t *TUI) viewFile(item *common.FileEntry) {
	pager := os.Getenv("PAGER")
	if pager == "" {
		pager = "less"
	}

	// Restore terminal for pager
	oldState, _ := makeRaw(os.Stdin.Fd())
	restore(os.Stdin.Fd(), oldState)
	fmt.Print("\033[?25h")

	cmd := exec.Command(pager, item.Name)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()
}

func (t *TUI) drawHelp() {
	// Draw a help dialog box
	helpLines := []string{
		"",
		"       up/down, k/j    Move cursor up/down",
		"    pgup/pgdn, g/G     Move cursor top/bottom",
		"   enter, right, l     Go to directory/device",
