func (t *TUI) currentItems() []*common.FileEntry {
	items := make([]*common.FileEntry, len(t.currentDir.Children))
	copy(items, t.currentDir.Children)
	t.sortItems(items)
	return items
}

func (t *TUI) sortItems(items []*common.FileEntry) {
	sort.SliceStable(items, func(i, j int) bool {
		a, b := items[i], items[j]
		var less bool
		switch t.sortBy {
		case "name":
			less = a.Name < b.Name
		case "itemCount":
			less = a.TotalItemCount() < b.TotalItemCount()
		case "mtime":
			less = a.LatestMtime().Before(b.LatestMtime())
		default: // "size"
			var sa, sb int64
			if t.showApparent {
				sa = a.TotalASize()
				sb = b.TotalASize()
			} else {
				sa = a.TotalDSize()
				sb = b.TotalDSize()
			}
			less = sa < sb
		}
		if t.sortOrder == "desc" {
			return !less
		}
		return less
	})
}

