func (t *TUI) getSelectedItem() *common.FileEntry {
	items := t.currentItems()
	hasParent := t.currentDir.Parent != nil

	idx := t.cursor
	if hasParent {
		if idx == 0 {
			return nil // parent entry selected
		}
		idx--
	}

	if idx >= 0 && idx < len(items) {
		return items[idx]
	}
	return nil
}

func (t *TUI) handleKey(key []byte) bool {
	s := string(key)

	if t.showHelp {
		// Any key closes help
		t.showHelp = false
		return false
	}

	if t.showInfo {
		t.showInfo = false
		return false
	}

	switch {
	case s == "q" || s == "Q" || s == "\x03": // q, Q, Ctrl+C
		if s == "Q" {
			// Print current directory path
			fmt.Printf("\n%s\n", t.currentDir.Name)
		}
		return true

	case s == "?" : // help
		t.showHelp = true

	case s == "\033[A" || s == "k": // up
		if t.cursor > 0 {
			t.cursor--
		}

	case s == "\033[B" || s == "j": // down
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		if t.cursor < maxCursor {
			t.cursor++
		}

	case s == "\033[C" || s == "\r" || s == "l" || s == "\n": // right/enter
		t.enterSelected()

	case s == "\033[D" || s == "h": // left
		t.goToParent()

	case s == "g" || s == "\033[1~" || s == "\033[H": // home/g - go to top
		t.cursor = 0

	case s == "G" || s == "\033[4~" || s == "\033[F": // end/G - go to bottom
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		t.cursor = maxCursor

	case s == "\033[5~": // PgUp
		t.cursor -= t.height - 3
		if t.cursor < 0 {
			t.cursor = 0
		}

	case s == "\033[6~": // PgDn
		items := t.currentItems()
		hasParent := t.currentDir.Parent != nil
		maxCursor := len(items) - 1
		if hasParent {
			maxCursor++
		}
		t.cursor += t.height - 3
		if t.cursor > maxCursor {
			t.cursor = maxCursor
		}

	case s == "n": // sort by name
		if t.sortBy == "name" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "name"
			t.sortOrder = "asc"
		}

	case s == "s": // sort by size
		if t.sortBy == "size" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "size"
			t.sortOrder = "desc"
		}

	case s == "c": // sort by item count
		if t.sortBy == "itemCount" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "itemCount"
			t.sortOrder = "desc"
		}

	case s == "m": // sort by mtime (or toggle mtime display in interactive? no, here it's sort)
		if t.sortBy == "mtime" {
			if t.sortOrder == "desc" {
				t.sortOrder = "asc"
			} else {
				t.sortOrder = "desc"
			}
		} else {
			t.sortBy = "mtime"
			t.sortOrder = "desc"
		}

	case s == "a": // toggle apparent size
		t.showApparent = !t.showApparent

	case s == "B": // toggle relative size
		t.showRelative = !t.showRelative

	case s == "r": // rescan
		t.rescan()

	case s == "i": // show info
		t.showInfo = !t.showInfo

	case s == "d": // delete
		if !t.cfg.NoDelete {
			t.deleteSelected()
		}

	case s == " ": // mark/unmark
		item := t.getSelectedItem()
		if item != nil {
			if t.markedItems[item] {
				delete(t.markedItems, item)
			} else {
				t.markedItems[item] = true
			}
		}

	case s == "u": // unmark all
		t.markedItems = make(map[*common.FileEntry]bool)

	case s == "b": // spawn shell
		if !t.cfg.NoSpawnShell {
			t.spawnShell()
		}

	case s == "v": // view file content
		item := t.getSelectedItem()
		if item != nil && !item.IsDir {
			t.viewFile(item)
		}
	}

	return false
}

func (t *TUI) enterSelected() {
	items := t.currentItems()
	hasParent := t.currentDir.Parent != nil

	idx := t.cursor
	if hasParent {
		if idx == 0 {
			t.goToParent()
			return
		}
		idx--
	}

	if idx >= 0 && idx < len(items) {
		item := items[idx]
		if item.IsDir {
			t.currentDir = item
			t.cursor = 0
			t.offset = 0
		}
	}
}

func (t *TUI) goToParent() {
	if t.currentDir.Parent != nil {
		parent := t.currentDir.Parent
		// Find the current dir in parent's children to set cursor
		t.currentDir = parent
		t.cursor = 0
		t.offset = 0
	}
}

func (t *TUI) rescan() {
	scanner := analyze.NewScanner(t.cfg.ScanConfig)

	path := t.currentDir.Name
	entry, err := scanner.ScanPath(path)
	if err != nil {
		return
	}

	// Update current dir
	if t.currentDir == t.root {
		t.root = entry
		t.currentDir = entry
	} else {
		t.currentDir.Children = entry.Children
	}
	t.cursor = 0
	t.offset = 0
}

func (t *TUI) deleteSelected() {
	item := t.getSelectedItem()
	if item == nil {
		return
	}

	// Confirm dialog would be nice but let's skip for now
	path := item.Name
	if item.IsDir {
		os.RemoveAll(path)
	} else {
		os.Remove(path)
	}

	// Remove from parent's children
	parent := t.currentDir
	for i, c := range parent.Children {
		if c == item {
			parent.Children = append(parent.Children[:i], parent.Children[i+1:]...)
			break
		}
	}

	if t.cursor >= len(parent.Children) {
		t.cursor = len(parent.Children) - 1
	}
	if t.cursor < 0 {
		t.cursor = 0
	}
}

func (t *TUI) spawnShell() {
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "/bin/sh"
	}

	// Restore terminal
	restore(os.Stdin.Fd(), nil)
	fmt.Print("\033[?25h")
	fmt.Print("\033[2J\033[H")

	cmd := exec.Command(shell)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Dir = t.currentDir.Name
	cmd.Run()

	// Re-enter raw mode (done by caller)
}

func (t *TUI) viewFile(item *common.FileEntry) {
	pager := os.Getenv("PAGER")
	if pager == "" {
		pager = "less"
	}

	// Restore terminal for pager
	oldState, _ := makeRaw(os.Stdin.Fd())
	restore(os.Stdin.Fd(), oldState)
	fmt.Print("\033[?25h")

	cmd := exec.Command(pager, item.Name)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Run()
}

func (t *TUI) drawHelp() {
	// Draw a help dialog box
	helpLines := []string{
		"",
		"       up/down, k/j    Move cursor up/down",
		"    pgup/pgdn, g/G     Move cursor top/bottom",
		"   enter, right, l     Go to directory/device",
		"           left, h     Go to parent directory",
		"",
		"                 r     Rescan current directory",
		"                 E     Export analysis data to file as JSON",
		"                 /     Search items by name",
		"                 a     Toggle between showing disk usage and apparent size",
		"                 B     Toggle bar alignment to biggest file or directory",
		"                 c     Show/hide file count",
		"                 m     Show/hide latest mtime",
		"                 b     Spawn shell in current directory",
		"                 q     Quit gdu",
		"                 Q     Quit gdu and print current directory path",
		"",
		"  Item under cursor:",
		"                 d     Delete file or directory",
		"                 e     Empty file or directory",
		"                 space Mark file or directory for deletion",
		"                 I     Ignore file or directory",
		"                 v     Show content of file",
		"                 o     Open file or directory in external program",
		"                 i     Show info about item",
		"",
		"",
	}

	title := " gdu help "
	boxWidth := 80
	boxHeight := len(helpLines) + 2

	startRow := 1
	startCol := (t.width - boxWidth) / 2
	if startCol < 0 {
		startCol = 0
	}

	// Draw box
	fmt.Printf("\033[%d;%dH", startRow, startCol+1)
	borderTop := "╔" + strings.Repeat("═", (boxWidth-2-utf8.RuneCountInString(title))/2) + title +
		strings.Repeat("═", boxWidth-2-utf8.RuneCountInString(title)-(boxWidth-2-utf8.RuneCountInString(title))/2) + "╗"
	if t.cfg.NoColor {
		fmt.Print(borderTop)
	} else {
		fmt.Print(colorHeader + borderTop + colorReset)
	}

	for i, line := range helpLines {
		row := startRow + 1 + i
		fmt.Printf("\033[%d;%dH", row, startCol+1)
		content := fmt.Sprintf("║%-*s║", boxWidth-2, line)
		if t.cfg.NoColor {
			fmt.Print(content)
		} else {
			fmt.Print(colorHeader + content + colorReset)
		}
		_ = boxHeight
	}

	fmt.Printf("\033[%d;%dH", startRow+1+len(helpLines), startCol+1)
	borderBottom := "╚" + strings.Repeat("═", boxWidth-2) + "╝"
	if t.cfg.NoColor {
		fmt.Print(borderBottom)
	} else {
		fmt.Print(colorHeader + borderBottom + colorReset)
	}
}

func (t *TUI) drawItemInfo(item *common.FileEntry) {
	_ = item
	// Simple info display - TODO
}

// formatSize formats a size using binary prefixes
func formatSize(size int64, si bool, kib bool, noPrefix bool) string {
	const (
		KiB int64 = 1024
		MiB       = KiB * 1024
		GiB       = MiB * 1024
		TiB       = GiB * 1024
		PiB       = TiB * 1024
		EiB       = PiB * 1024
	)

	v := float64(size)
	var s string
	switch {
	case size < KiB:
		s = fmt.Sprintf("%d B", size)
	case size < MiB:
		s = fmt.Sprintf("%.1f KiB", v/float64(KiB))
	case size < GiB:
		s = fmt.Sprintf("%.1f MiB", v/float64(MiB))
	case size < TiB:
		s = fmt.Sprintf("%.1f GiB", v/float64(GiB))
	case size < PiB:
		s = fmt.Sprintf("%.1f TiB", v/float64(TiB))
	case size < EiB:
		s = fmt.Sprintf("%.1f PiB", v/float64(PiB))
	default:
		s = fmt.Sprintf("%.1f EiB", v/float64(EiB))
	}

	w := 10
	if len(s)+1 > w {
		w = len(s) + 1
	}
	return fmt.Sprintf("%*s", w, s)
}

// Terminal raw mode handling
type termios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [20]uint8
	Ispeed uint32
	Ospeed uint32
}

func makeRaw(fd uintptr) (*termios, error) {
	var old termios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCGETS, uintptr(unsafe.Pointer(&old)))
	if errno != 0 {
		return nil, errno
	}

	new := old
	// Set raw mode flags
	new.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP |
		syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	new.Oflag &^= syscall.OPOST
	new.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	new.Cflag &^= syscall.CSIZE | syscall.PARENB
	new.Cflag |= syscall.CS8
	new.Cc[syscall.VMIN] = 1
	new.Cc[syscall.VTIME] = 0

	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCSETS, uintptr(unsafe.Pointer(&new)))
	if errno != 0 {
		return nil, errno
	}

	return &old, nil
}

func restore(fd uintptr, state *termios) {
	if state == nil {
		return
	}
	syscall.Syscall(syscall.SYS_IOCTL, fd, syscall.TCSETS, uintptr(unsafe.Pointer(state)))
}

type winsize struct {
	Row    uint16
	Col    uint16
	Xpixel uint16
	Ypixel uint16
}

func getTermSize() (int, int) {
	var ws winsize
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, os.Stdout.Fd(), syscall.TIOCGWINSZ, uintptr(unsafe.Pointer(&ws)))
	if errno != 0 {
		return 80, 24
	}
	return int(ws.Col), int(ws.Row)
}

