// TUIConfig holds configuration for the TUI
type TUIConfig struct {
	ShowApparent    bool
	ShowRelativeSize bool
	ShowItemCount   bool
	ShowMtime       bool
	NoColor         bool
	NoUnicode       bool
	Mouse           bool
	NoDelete        bool
	NoSpawnShell    bool
