		"",
		"  Item under cursor:",
		"                 d     Delete file or directory",
		"                 e     Empty file or directory",
		"                 space Mark file or directory for deletion",
		"                 I     Ignore file or directory",
		"                 v     Show content of file",
		"                 o     Open file or directory in external program",
		"                 i     Show info about item",
		"",
		"",
	}

	title := " gdu help "
	boxWidth := 80
	boxHeight := len(helpLines) + 2

	startRow := 1
	startCol := (t.width - boxWidth) / 2
	if startCol < 0 {
		startCol = 0
	}

	// Draw box
	fmt.Printf("\033[%d;%dH", startRow, startCol+1)
	borderTop := "╔" + strings.Repeat("═", (boxWidth-2-utf8.RuneCountInString(title))/2) + title +
		strings.Repeat("═", boxWidth-2-utf8.RuneCountInString(title)-(boxWidth-2-utf8.RuneCountInString(title))/2) + "╗"
	if t.cfg.NoColor {
		fmt.Print(borderTop)
