func runTUI(root *common.FileEntry, cfg *Config, scanCfg *analyze.ScanConfig) error {
	tuiCfg := &tui.TUIConfig{
		ShowApparent:    cfg.ShowApparent,
		ShowRelativeSize: cfg.ShowRelativeSize,
		ShowItemCount:   cfg.ShowItemCount,
		ShowMtime:       cfg.ShowMtime,
		NoColor:         cfg.NoColor,
		NoUnicode:       cfg.NoUnicode,
		Mouse:           cfg.Mouse,
