func isTerminal(fd uintptr) bool {
	var termios struct {
		Iflag  uint32
		Oflag  uint32
		Cflag  uint32
		Lflag  uint32
		Cc     [20]uint8
		Ispeed uint32
		Ospeed uint32
	}
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd,
		syscall.TCGETS, uintptr(unsafe.Pointer(&termios)))
	return errno == 0
}

