	t := tui.New(tuiCfg)
	t.SetRoot(root)
	return t.RunWithRoot(targetPath)
}

func buildScanConfig(cfg *Config) *analyze.ScanConfig {
	scanCfg := &analyze.ScanConfig{
		IgnoreDirs:     cfg.IgnoreDirs,
		IgnoreHidden:   cfg.IgnoreHidden,
		NoCross:        cfg.NoCross,
		FollowSymlinks: cfg.FollowSymlinks,
		MaxCores:       cfg.MaxCores,
	}

	// Parse ignore patterns
	for _, pat := range cfg.IgnoreDirsPattern {
		re, err := regexp.Compile(pat)
		if err != nil {
			fmt.Fprintf(os.Stderr, "Error: error parsing regexp: %s\n", err)
			os.Exit(1)
		}
		scanCfg.IgnoreDirPatterns = append(scanCfg.IgnoreDirPatterns, re)
	}

	// Parse type filters
	if len(cfg.IncludeTypes) > 0 {
		scanCfg.IncludeTypes = make(map[string]bool)
		for _, t := range cfg.IncludeTypes {
			for _, part := range strings.Split(t, ",") {
				scanCfg.IncludeTypes[strings.TrimSpace(part)] = true
			}
		}
	}
	if len(cfg.ExcludeTypes) > 0 {
		scanCfg.ExcludeTypes = make(map[string]bool)
		for _, t := range cfg.ExcludeTypes {
			for _, part := range strings.Split(t, ",") {
				scanCfg.ExcludeTypes[strings.TrimSpace(part)] = true
			}
		}
	}

	// Parse age/time filters
	now := time.Now()
	if cfg.MaxAge != "" {
		if d := parseDuration(cfg.MaxAge); d > 0 {
			t := now.Add(-d)
			scanCfg.MaxAge = &t
		}
	}
	if cfg.MinAge != "" {
		if d := parseDuration(cfg.MinAge); d > 0 {
			t := now.Add(-d)
			scanCfg.MinAge = &t
		}
	}
	if cfg.Since != "" {
		t := parseTimeOrDate(cfg.Since)
		if !t.IsZero() {
			scanCfg.Since = &t
		}
	}
	if cfg.Until != "" {
		t := parseTimeOrDate(cfg.Until)
		if !t.IsZero() {
			// For date-only: include the whole day
			if len(cfg.Until) == 10 {
				t = t.Add(24*time.Hour - 1)
			}
			scanCfg.Until = &t
		}
	}

	// Read ignore-from file
	if cfg.IgnoreFrom != "" {
		pats := readIgnoreFile(cfg.IgnoreFrom)
		for _, pat := range pats {
			re, err := regexp.Compile(pat)
			if err != nil {
				continue
			}
			scanCfg.IgnoreDirPatterns = append(scanCfg.IgnoreDirPatterns, re)
		}
	}

	return scanCfg
}

func parseDuration(s string) time.Duration {
	var total time.Duration
	i := 0
	for i < len(s) {
		numStart := i
		for i < len(s) && s[i] >= '0' && s[i] <= '9' {
			i++
		}
		if i == numStart {
			break
		}
		numStr := s[numStart:i]
		var num int
		fmt.Sscanf(numStr, "%d", &num)

		unitStart := i
		for i < len(s) && (s[i] < '0' || s[i] > '9') {
			i++
		}
		unit := s[unitStart:i]

		switch unit {
		case "s":
			total += time.Duration(num) * time.Second
		case "m":
			total += time.Duration(num) * time.Minute
		case "h":
			total += time.Duration(num) * time.Hour
		case "d":
			total += time.Duration(num) * 24 * time.Hour
		case "w":
			total += time.Duration(num) * 7 * 24 * time.Hour
		case "mo":
			total += time.Duration(num) * 30 * 24 * time.Hour
		case "y":
			total += time.Duration(num) * 365 * 24 * time.Hour
		}
	}
	return total
}

func parseTimeOrDate(s string) time.Time {
	t, err := time.Parse(time.RFC3339, s)
	if err == nil {
		return t
	}
	t, err = time.ParseInLocation("2006-01-02", s, time.Local)
	if err == nil {
		return t
	}
	return time.Time{}
}

func readIgnoreFile(path string) []string {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var pats []string
	for _, line := range strings.Split(string(data), "\n") {
		line = strings.TrimSpace(line)
		if line != "" && !strings.HasPrefix(line, "#") {
			pats = append(pats, line)
		}
	}
	return pats
}

func printVersion() {
	fmt.Printf("Version:\t %s\n", gduVersion)
	fmt.Printf("Built time:\t %s\n", gduBuildTime)
	fmt.Printf("Built user:\t %s\n", gduBuildUser)
}

type ioctlTermios struct {
	Iflag  uint32
	Oflag  uint32
	Cflag  uint32
	Lflag  uint32
	Cc     [20]uint8
	Ispeed uint32
	Ospeed uint32
}

func isTerminal(fd uintptr) bool {
	var t ioctlTermios
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd,
		syscall.TCGETS, uintptr(unsafe.Pointer(&t)))
	return errno == 0
}
