				return nil, fmt.Errorf("flag needs an argument: %s", arg)
			}
			cfg.Until = args[i]
		case "-D", "--db":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: %s", arg)
			}
			cfg.DB = args[i]
		case "--storage":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: %s", arg)
			}
			cfg.Storage = args[i]
		case "--style":
			i++
			if i >= len(args) {
				return nil, fmt.Errorf("flag needs an argument: %s", arg)
			}
			cfg.Style = args[i]
		default:
			// Handle --flag=value format
			if strings.Contains(arg, "=") {
				parts := strings.SplitN(arg, "=", 2)
				newArgs := append([]string{parts[0], parts[1]}, args[i+1:]...)
				args = append(args[:i], newArgs...)
				continue
			}
			err = fmt.Errorf("unknown flag: %s", arg)
		}

		if err != nil {
			return nil, err
		}
		i++
	}

	return remaining, nil
}

