// SetRoot sets the root entry for the TUI (for JSON input mode)
func (t *TUI) SetRoot(root *common.FileEntry) {
	t.root = root
	if root.IsDir {
		t.currentDir = root
	}
}

// RunWithRoot runs the TUI with a pre-loaded root (for JSON input mode)
func (t *TUI) RunWithRoot(path string) error {
	if t.root == nil {
		return t.Run(path)
	}

	// Set up terminal
	oldState, err := makeRaw(os.Stdin.Fd())
	if err != nil {
		return err
	}
	defer restore(os.Stdin.Fd(), oldState)

	t.width, t.height = getTermSize()
	fmt.Print("\033[?25l")
	fmt.Print("\033[2J\033[H")
	defer func() {
		fmt.Print("\033[?25h")
		fmt.Print("\033[2J\033[H")
	}()

	t.render()

	buf := make([]byte, 16)
	for {
		n, err := os.Stdin.Read(buf)
		if err != nil {
			break
		}
		if n == 0 {
			continue
		}

		key := buf[:n]
		if t.handleKey(key) {
			break
		}

		t.width, t.height = getTermSize()
		t.render()
	}

	return nil
}
