	IsDir        bool
	IsSymlink    bool
	ASize        int64
	DSize        int64
	Mtime        time.Time
	HardLink     bool // has hard links (nlink > 1) - shows H flag
	DupHardLink  bool // duplicate hard link (same inode, already counted) - DSize excluded from total
	Inode        uint64
	Device       uint64
	Parent       *FileEntry
	Children     []*FileEntry
	ReadError    bool
	SubReadError bool
	NotrReg      bool // not regular (symlink, socket, etc.)
}

// GetFlag returns the flag character for display
func (f *FileEntry) GetFlag() byte {
	if f.ReadError {
		return FlagError
	}
	if f.SubReadError {
		return FlagSubError
	}
	if f.IsSymlink || f.NotrReg {
		return FlagSymlink
	}
	if f.HardLink {
		return FlagHardLink
	}
	if f.IsDir && len(f.Children) == 0 && !f.ReadError {
		return FlagEmpty
	}
	return FlagNone
}

// GetDisplayName returns the name to display
func (f *FileEntry) GetDisplayName() string {
	if f.IsDir {
		return "/" + f.Name
	}
	return f.Name
}

// TotalDSize returns total disk size (for directories: sum of children + self)
// Duplicate hard links are excluded
func (f *FileEntry) TotalDSize() int64 {
	if f.DupHardLink {
		return 0
	}
	if f.IsDir {
		total := f.DSize
		for _, c := range f.Children {
			total += c.TotalDSize()
		}
		return total
	}
	return f.DSize
}

// DisplayDSize returns the disk size for display (including duplicates)
func (f *FileEntry) DisplayDSize() int64 {
	if f.IsDir {
		total := f.DSize
		for _, c := range f.Children {
			total += c.TotalDSize()
		}
		return total
	}
	return f.DSize
}

// TotalASize returns total apparent size
func (f *FileEntry) TotalASize() int64 {
	if f.IsDir {
		total := f.ASize
		for _, c := range f.Children {
			total += c.TotalASize()
		}
		return total
	}
	return f.ASize
}

// GetDisplaySize returns the size to display (disk or apparent)
// For individual items in a list (not total), show actual dsize even for duplicates
func (f *FileEntry) GetDisplaySize(apparent bool) int64 {
	if apparent {
		return f.TotalASize()
	}
	// For directories: use TotalDSize (which excludes dup hardlinks)
	if f.IsDir {
		return f.TotalDSize()
	}
	// For files: show actual dsize (including for dup hardlinks)
	return f.DSize
}

// TotalItemCount returns number of items recursively
func (f *FileEntry) TotalItemCount() int64 {
	if f.IsDir {
		var total int64 = 1
		for _, c := range f.Children {
			total += c.TotalItemCount()
		}
		return total
	}
	return 1
}

// LatestMtime returns the latest modification time recursively
func (f *FileEntry) LatestMtime() time.Time {
	latest := f.Mtime
	for _, c := range f.Children {
		if ct := c.LatestMtime(); ct.After(latest) {
			latest = ct
		}
	}
	return latest
}
GOEOF

