package analyze

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"sync"
	"syscall"
	"time"

	"gdu/common"
)

// ScanConfig holds scanning configuration
type ScanConfig struct {
	IgnoreDirs        []string
	IgnoreDirPatterns []*regexp.Regexp
	IgnoreHidden      bool
	NoCross           bool
	FollowSymlinks    bool
	MaxCores          int
	MaxAge            *time.Time
	MinAge            *time.Time
	Since             *time.Time
	Until             *time.Time
	IncludeTypes      map[string]bool
	ExcludeTypes      map[string]bool
}

// Scanner scans the filesystem
type Scanner struct {
	config  *ScanConfig
	rootDev uint64
	mu      sync.Mutex
	inodes  map[uint64]bool // tracks seen inodes for hard link dedup
}

// NewScanner creates a new scanner
func NewScanner(config *ScanConfig) *Scanner {
	return &Scanner{
		config: config,
		inodes: make(map[uint64]bool),
	}
}

// ScanPath scans a path and returns a file entry tree
func (s *Scanner) ScanPath(path string) (*common.FileEntry, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		abs = path
	}

	info, err := os.Lstat(abs)
	if err != nil {
		return nil, err
	}

	stat := info.Sys().(*syscall.Stat_t)
	s.rootDev = stat.Dev

	entry := &common.FileEntry{
		Name:  abs,
		IsDir: info.IsDir(),
		Mtime: info.ModTime(),
		ASize: info.Size(),
	}

	if info.IsDir() {
		entry.DSize = 4096
		s.scanDir(entry, abs)
	} else {
		entry.DSize = int64(stat.Blocks) * 512
	}

	return entry, nil
}

func (s *Scanner) shouldIgnorePath(path string) bool {
	for _, dir := range s.config.IgnoreDirs {
		if dir == path {
			return true
		}
	}
	for _, pat := range s.config.IgnoreDirPatterns {
		if pat.MatchString(path) {
			return true
		}
	}
	return false
}

func (s *Scanner) scanDir(dirEntry *common.FileEntry, dirPath string) {
	entries, err := os.ReadDir(dirPath)
	if err != nil {
		dirEntry.ReadError = true
		return
	}

	for _, de := range entries {
		name := de.Name()
		fullPath := filepath.Join(dirPath, name)

		// Check if should ignore
		if s.shouldIgnorePath(fullPath) {
			continue
		}

		// Check hidden dirs (only dirs, not files)
		if s.config.IgnoreHidden && strings.HasPrefix(name, ".") && de.IsDir() {
