# Now let me fix the printDepth function
# The key insight is:
# - Print root with full path
# - For each child (sorted by size desc, name desc), print with full path
# - If child is a dir and within depth, recurse into it
# - Files don't recurse

cat > /workspace/output/print.go << 'GOEOF'
package output

import (
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sort"
	"strings"

	"gdu/common"
)

// PrintConfig holds configuration for printing
type PrintConfig struct {
	ShowApparent bool
	SI           bool
	KiB          bool
	NoPrefix     bool
	ReverseSort  bool
	Top          int
	Depth        int
	Summarize    bool
}

// getDisplaySize returns the size for display of an individual item in a listing
func getDisplaySize(entry *common.FileEntry, cfg *PrintConfig) int64 {
	if cfg.ShowApparent {
		return entry.TotalASize()
	}
	return entry.GetDisplaySize(false)
}

// getTotalSize returns the total size (excluding dup hardlinks)
func getTotalSize(entry *common.FileEntry, cfg *PrintConfig) int64 {
	if cfg.ShowApparent {
		return entry.TotalASize()
	}
	return entry.TotalDSize()
}

// PrintResults prints the analysis results to stdout
func PrintResults(root *common.FileEntry, cfg *PrintConfig) {
	w := os.Stdout

	if cfg.Summarize {
		printSummarize(w, root, cfg)
		return
	}

	if cfg.Top > 0 {
		printTop(w, root, cfg)
		return
	}

	if cfg.Depth > 0 {
		// Print root
		rootSize := getTotalSize(root, cfg)
		rootSizeStr := common.FormatSizeSummarize(rootSize, cfg.SI, cfg.KiB, cfg.NoPrefix)
		fmt.Fprintf(w, "%s %s\n", rootSizeStr, root.Name)
		// Print contents recursively
		printDepthChildren(w, root, root.Name, cfg, 1)
		return
	}

	// Default: show direct children sorted by size
	printChildren(w, root, cfg)
}

func printSummarize(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	size := getTotalSize(root, cfg)
	sizeStr := common.FormatSizeSummarize(size, cfg.SI, cfg.KiB, cfg.NoPrefix)
	name := root.Name
	name = strings.TrimSuffix(name, "/")
	parts := strings.Split(name, "/")
	basename := parts[len(parts)-1]
	fmt.Fprintf(w, "%s %s\n", sizeStr, basename)
}

// printDepthChildren prints children recursively for depth mode
func printDepthChildren(w io.Writer, dir *common.FileEntry, dirPath string, cfg *PrintConfig, currentDepth int) {
	children := make([]*common.FileEntry, len(dir.Children))
	copy(children, dir.Children)

	// Sort: size DESC, name DESC for ties
	sort.SliceStable(children, func(i, j int) bool {
		si := getDisplaySize(children[i], cfg)
		sj := getDisplaySize(children[j], cfg)
		if si != sj {
			return si > sj
		}
		return children[i].Name > children[j].Name
	})

	for _, child := range children {
		fullPath := filepath.Join(dirPath, child.Name)
		childSize := getDisplaySize(child, cfg)
		childSizeStr := common.FormatSizeSummarize(childSize, cfg.SI, cfg.KiB, cfg.NoPrefix)
		fmt.Fprintf(w, "%s %s\n", childSizeStr, fullPath)

		if child.IsDir && currentDepth < cfg.Depth {
			printDepthChildren(w, child, fullPath, cfg, currentDepth+1)
		}
	}
}

func printTop(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	var files []*common.FileEntry
	collectFiles(root, &files)

	// Sort by apparent size descending (always for --top)
	sort.SliceStable(files, func(i, j int) bool {
		si := files[i].TotalASize()
		sj := files[j].TotalASize()
		if si != sj {
			return si > sj
		}
		return files[i].Name > files[j].Name
	})

	count := cfg.Top
	if count > len(files) {
		count = len(files)
	}

	for i := 0; i < count; i++ {
		f := files[i]
		size := getDisplaySize(f, cfg)
		sizeStr := common.FormatSizeSummarize(size, cfg.SI, cfg.KiB, cfg.NoPrefix)
		fmt.Fprintf(w, "%s %s\n", sizeStr, f.Name)
	}
}

func collectFiles(entry *common.FileEntry, files *[]*common.FileEntry) {
	if entry.IsDir {
		for _, child := range entry.Children {
			collectFiles(child, files)
		}
	} else {
		*files = append(*files, entry)
	}
}

func printChildren(w io.Writer, root *common.FileEntry, cfg *PrintConfig) {
	children := make([]*common.FileEntry, len(root.Children))
