# That's with MY colors ([33m yellow)
# The original uses [31m (red)

# Let me just update the format to match what the original does more closely
# The exact format per line (non-selected) is:
# flag + \033[1;31m + justTheNumber + \033[39m + " " + unit + " " + bar + nameColored + \033[0m\033[39m\033[49m

old_drawItem = '''func (t *TUI) drawItem(entry *common.FileEntry, isSelected bool) {
